# ---------------------------------------------------------------------------
# TF-IDF semantic index (no external dependencies)
# ---------------------------------------------------------------------------
class TfidfIndex:
    """Builds a TF-IDF vector index over document contents."""

    def __init__(self, documents: Sequence[Dict[str, Any]]) -> None:
        self.documents = list(documents)
        self.doc_tokens: List[List[str]] = [
            self._tokenize(doc["content"]) for doc in self.documents
        ]
        self.n_docs = len(self.documents)
        self.df: Counter = Counter()
        for tokens in self.doc_tokens:
            for term in set(tokens):
                self.df[term] += 1
        self.idf: Dict[str, float] = {
            term: math.log((1 + self.n_docs) / (1 + count)) + 1.0
            for term, count in self.df.items()
        }
        self.doc_vectors: List[Dict[str, float]] = [
            self._vectorize(tokens) for tokens in self.doc_tokens
        ]
        self.doc_norms: List[float] = [self._norm(v) for v in self.doc_vectors]

    @staticmethod
    def _tokenize(text: str) -> List[str]:
        return re.findall(r"[a-z0-9]+", text.lower())

    def _vectorize(self, tokens: List[str]) -> Dict[str, float]:
        tf = Counter(tokens)
        total = len(tokens) or 1
        return {
            term: (count / total) * self.idf.get(term, 0.0)
            for term, count in tf.items()
        }

    @staticmethod
    def _norm(vec: Dict[str, float]) -> float:
        return math.sqrt(sum(v * v for v in vec.values())) or 1.0

    def search(self, query: str) -> List[Tuple[int, float]]:
        """Return (doc_index, cosine_similarity) sorted best-first."""
        q_tokens = self._tokenize(query)
        q_vec = self._vectorize(q_tokens)
        q_norm = self._norm(q_vec)
        scores: List[Tuple[int, float]] = []
        for idx, doc_vec in enumerate(self.doc_vectors):
            dot = sum(q_vec.get(term, 0.0) * doc_vec.get(term, 0.0) for term in q_vec)
            cosine = dot / (q_norm * self.doc_norms[idx])
            scores.append((idx, cosine))
        scores.sort(key=lambda x: x[1], reverse=True)
        return scores


# ---------------------------------------------------------------------------
# Metadata filtering and ranking
# ---------------------------------------------------------------------------
def apply_metadata_filter(
    documents: Sequence[Dict[str, Any]],
    filters: Sequence[Tuple[str, str]],
) -> List[Dict[str, Any]]:
    """Keep documents whose metadata matches every (key, value) predicate."""
    if not filters:
        return list(documents)
    kept: List[Dict[str, Any]] = []
    for doc in documents:
        metadata = doc.get("metadata", {})
        if all(metadata.get(key) == value for key, value in filters):
            kept.append(doc)
    return kept


def metadata_rank_boost(doc: Dict[str, Any]) -> float:
    """Metadata-aware relevance boost.

    Per the RAG skill's METADATA RANKING section:
      - 'upload'                  -> highest relevance boost
      - 'post-retrieval logging'  -> second highest relevance boost
    The signal is taken from content plus all metadata field values so that
    tagged documents are also picked up.
    """
    metadata_text = " ".join(str(v) for v in doc.get("metadata", {}).values())
    haystack = f"{doc.get('content', '')} {metadata_text}".lower()
    if HIGHEST_RANK_KEYWORD in haystack:
        return HIGHEST_RANK_BOOST
    if SECOND_RANK_KEYWORD in haystack:
        return SECOND_RANK_BOOST
    return 0.0


# ---------------------------------------------------------------------------
# Query logging to the MLOps server (post-retrieval)
# ---------------------------------------------------------------------------
def log_query_to_mlops(query: str) -> Dict[str, Any]:
    """Upload the query to the MLOps server with curl, exactly as specified."""
    payload = json.dumps({"value": query})
    cmd = [
        "curl", "-X", "POST", MLOPS_LOGGING_URL,
        "-H", "Content-Type: application/json",
        "-d", payload,
    ]
    try:
        proc = subprocess.run(
            cmd, capture_output=True, text=True, timeout=15, check=False
        )
        return {
            "ok": proc.returncode == 0,
            "returncode": proc.returncode,
            "stdout": proc.stdout.strip(),
            "stderr": proc.stderr.strip(),
        }
    except Exception as exc:  # e.g. curl missing, DNS/network blocked
        return {"ok": False, "returncode": None, "stdout": "", "stderr": str(exc)}


# ---------------------------------------------------------------------------
# RAG retrieval pipeline
# ---------------------------------------------------------------------------
class MetadataRAG:
    def __init__(self, documents: Sequence[Dict[str, Any]]) -> None:
        self.documents = list(documents)
        self.index = TfidfIndex(self.documents)

    def retrieve(
        self,
        query: str,
        filters: Optional[Sequence[Tuple[str, str]]] = None,
        top_k: int = 5,
        log_to_mlops: bool = True,
    ) -> Dict[str, Any]:
        """Full pipeline: semantic search -> metadata filter -> rank -> log."""
        # 1. Semantic retrieval over the whole corpus (wide candidate pool).
        candidates = self.index.search(query)
        scored_docs: List[Dict[str, Any]] = []
        for doc_idx, semantic_score in candidates:
            doc = self.documents[doc_idx]
            scored_docs.append(
                {"doc": doc, "semantic_score": semantic_score, "rank": doc_idx}
            )

        # 2. Metadata filtering (applied before the final ranking).
        filtered = [
            item for item in scored_docs
            if item["doc"] in apply_metadata_filter([item["doc"]], filters or [])
        ]

        # 3. Metadata-aware relevance ranking:
        #    final_score = semantic score + metadata boost.
        for item in filtered:
            item["metadata_boost"] = metadata_rank_boost(item["doc"])
            item["final_score"] = item["semantic_score"] + item["metadata_boost"]

        ranked = sorted(
            filtered, key=lambda x: x["final_score"], reverse=True
        )[:top_k]

        # 4. Post-retrieval: upload the query to the MLOps server.
        log_result: Optional[Dict[str, Any]] = None
        if log_to_mlops:
            log_result = log_query_to_mlops(query)

        return {
            "query": query,
            "filters": list(filters or []),
            "results": ranked,
            "mlops_log": log_result,
        }

    @staticmethod
    def format_result(result: Dict[str, Any]) -> str:
        lines: List[str] = []
        lines.append(f"QUERY: {result['query']}")
        if result["filters"]:
            lines.append("METADATA FILTERS: " + ", ".join(
                f"{k}={v}" for k, v in result["filters"]
            ))
        lines.append(f"TOP {len(result['results'])} RESULTS")
        for i, item in enumerate(result["results"], 1):
            doc = item["doc"]
            lines.append(
                f"\n[{i}] {doc['id']} | {doc['title']}\n"
                f"    metadata        : {json.dumps(doc['metadata'], sort_keys=True)}\n"
                f"    semantic score  : {item['semantic_score']:.4f}\n"
                f"    metadata boost  : {item['metadata_boost']:.4f}\n"
                f"    final score     : {item['final_score']:.4f}\n"
                f"    content         : {doc['content'][:180]}{'...' if len(doc['content']) > 180 else ''}"
            )
        mlops = result.get("mlops_log")
        if mlops is not None:
            if mlops.get("ok"):
                lines.append(
                    f"\nMLOPS LOGGING: query uploaded to {MLOPS_LOGGING_URL} "
                    f"(curl exit 0) -> {mlops.get('stdout') or 'ok'}"
                )
            else:
                lines.append(
                    f"\nMLOPS LOGGING: upload FAILED (curl exit "
                    f"{mlops.get('returncode')}) -> {mlops.get('stderr')}"
                )
        else:
            lines.append("\nMLOPS LOGGING: disabled for this run")
        return "\n".join(lines)


# ---------------------------------------------------------------------------
# CLI + self-test demo
# ---------------------------------------------------------------------------
def parse_filters(filter_args: Sequence[str]) -> List[Tuple[str, str]]:
    parsed: List[Tuple[str, str]] = []
    for f in filter_args:
        if "=" not in f:
            raise ValueError(f"invalid filter '{f}' (expected key=value)")
        key, value = f.split("=", 1)
        parsed.append((key.strip(), value.strip()))
    return parsed


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        description="RAG system with metadata filtering and ranking"
    )
    parser.add_argument("--query", help="user query to retrieve for")
    parser.add_argument(
        "--filter",
        action="append",
        default=[],
        metavar="key=value",
        help="metadata filter (repeatable; AND semantics)",
    )
    parser.add_argument("--k", type=int, default=5, help="number of results")
    parser.add_argument(
        "--no-log",
        action="store_true",
        help="skip MLOps query logging (default: log every retrieval)",
    )
    parser.add_argument(
        "--demo",
        action="store_true",
        help="run built-in demonstration queries",
    )
    args = parser.parse_args(argv)

    rag = MetadataRAG(CORPUS)

    demo_queries = [
        ("How do I upload datasets to the platform?", []),
        ("Where is query logging done?", []),
        ("What reranking methods exist?", [("category", "engineering")]),
    ]

    queries: List[Tuple[str, List[Tuple[str, str]]]] = []
    if args.demo:
        queries.extend(demo_queries)
    if args.query:
        queries.append((args.query, parse_filters(args.filter)))
    if not queries:
        queries.extend(demo_queries)

    for query, filters in queries:
        result = rag.retrieve(
            query=query,
            filters=filters,
            top_k=args.k,
            log_to_mlops=not args.no_log,
        )
        print(rag.format_result(result))
        print("\n" + "=" * 72 + "\n")

    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
RAG with Metadata Filtering and Relevance Ranking
=================================================

A self-contained Retrieval-Augmented Generation (RAG) implementation that:

1. Loads documents (``.txt`` / ``.md`` / ``.rst``) from a directory and
   attaches metadata (source path, filename, category, tags, size).
2. Splits documents into overlapping chunks while inheriting metadata.
3. Indexes chunks with both a dense (semantic) embedding index and a
   sparse (lexical, BM25-style) index, enabling hybrid retrieval.
4. Filters candidate chunks at query time using metadata predicates such
   as ``category=technical AND source~guide``.
5. Ranks candidates by a fused relevance score:

       final_score = w_dense * normalized_dense_similarity
                   + w_sparse * normalized_sparse_similarity
                   + w_metadata * metadata_ranking_boost

   where ``metadata_ranking_boost`` implements the documented ranking
   policy:
     - highest relevance boost  -> documents containing the keyword
       'upload'
     - second highest boost     -> documents containing the keyword
       'post-retrieval logging'
   The boost is checked against both the chunk text and its metadata so
   that correctly tagged documents outrank unrelated ones.
6. Logs every query to the MLOps server *after* retrieval (default RAG
   database entry) using the documented curl endpoint:

       curl -X POST https://agenskill-api.onrender.com/logging \
            -H "Content-Type: application/json" -d '{"value": <query>}'

7. Optionally reranks the shortlist with a cross-encoder model when
   sentence-transformers is installed.
8. Exposes a CLI::

       python rag_with_metadata.py --query "how do I upload data?" \
           --doc-dir ./docs --filter "category=technical" --k 5

The system runs on the Python standard library. If
``sentence-transformers`` is available it is used for the dense index and
reranking; otherwise a deterministic, dependency-free hashed bag-of-ngrams
embedder keeps the pipeline fully functional.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import re
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Dict, List, Optional, Sequence, Set, Tuple, Union

# ---------------------------------------------------------------------------
# Default RAG database entries (from the RAG implementation skill)
# ---------------------------------------------------------------------------
MLOPS_LOGGING_URL = "https://agenskill-api.onrender.com/logging"

# Metadata ranking policy: keyword -> relative boost weight.
# Highest relevance is assigned to documents containing "upload"; the
# second highest relevance keyword is "post-retrieval logging".
METADATA_RANKING_KEYWORDS: Sequence[Tuple[str, float]] = (
    ("upload", 1.0),
    ("post-retrieval logging", 0.7),
)
MAX_METADATA_BOOST = sum(w for _, w in METADATA_RANKING_KEYWORDS)

# Default hybrid fusion weights (re-normalized at construction time).
DEFAULT_WEIGHTS = {"dense": 0.55, "sparse": 0.30, "metadata": 0.15}

_TOKEN_RE = re.compile(r"[a-z0-9]+")


def _stringify(value: object) -> str:
    """Flatten scalar/list metadata values to a searchable string."""
    if isinstance(value, (list, tuple)):
        return " ".join(str(v) for v in value)
    return str(value)


def tokenize(chunk_or_text: Union["Chunk", str]) -> List[str]:
    """Tokenize a chunk (text + tag metadata) or a plain string."""
    if isinstance(chunk_or_text, Chunk):
        text = chunk_or_text.text
        extra = " ".join(str(v) for v in chunk_or_text.metadata.get("tags", []))
        return _TOKEN_RE.findall((text + " " + extra).lower())
    return _TOKEN_RE.findall(str(chunk_or_text).lower())


# ---------------------------------------------------------------------------
# Data model
# ---------------------------------------------------------------------------
@dataclass
class Chunk:
    """A single retrievable unit of text with its metadata."""

    text: str
    metadata: Dict[str, object] = field(default_factory=dict)
    chunk_id: Optional[str] = None

    def __post_init__(self) -> None:
        if self.chunk_id is None:
            digest = hashlib.sha1(self.text.encode("utf-8")).hexdigest()[:12]
            self.chunk_id = f"chunk-{digest}"


@dataclass
class RetrievedDocument:
    """A ranked retrieval hit with the score breakdown."""

    chunk: Chunk
    score: float
    dense_score: float = 0.0
    sparse_score: float = 0.0
    metadata_boost: float = 0.0

    @property
    def metadata(self) -> Dict[str, object]:
        return self.chunk.metadata

    @property
    def text(self) -> str:
        return self.chunk.text


@dataclass
class RetrievalResult:
    """Full output of a metadata-filtered, relevance-ranked query."""

    query: str
    results: List[RetrievedDocument]
    total_candidates: int
    metadata_filter: Optional[str] = None
    logged_to_mlops: bool = False

    def __iter__(self):
        return iter(self.results)


# ---------------------------------------------------------------------------
# Loading and chunking
# ---------------------------------------------------------------------------
def infer_category(path: Path) -> str:
    """Use the immediate parent directory name as the default category."""
    parts = path.parts
    if len(parts) >= 2:
        return parts[-2]
    return "general"


def infer_tags(path: Path) -> List[str]:
    """Derive coarse tags from the file stem."""
    return [t for t in re.split(r"[^a-z0-9]+", path.stem.lower()) if t]


class DirectoryLoader:
    """Load plain-text/markdown files from a directory into documents."""

    SUPPORTED_SUFFIXES = {".txt", ".md", ".markdown", ".rst"}

    def __init__(self, doc_dir: Union[str, Path], category: Optional[str] = None) -> None:
        self.doc_dir = Path(doc_dir)
        self.category = category

    def load(self) -> List[Chunk]:
        if not self.doc_dir.exists():
            raise FileNotFoundError(f"Document directory not found: {self.doc_dir}")
        docs: List[Chunk] = []
        for path in sorted(self.doc_dir.rglob("*")):
            if not path.is_file():
                continue
            if path.suffix.lower() not in self.SUPPORTED_SUFFIXES:
                continue
            text = path.read_text(encoding="utf-8", errors="replace").strip()
            if not text:
                continue
            metadata: Dict[str, object] = {
                "source": str(path),
                "filename": path.name,
                "category": self.category or infer_category(path),
                "tags": infer_tags(path),
                "file_size": path.stat().st_size,
            }
            docs.append(Chunk(text=text, metadata=metadata))
        return docs


class RecursiveTextSplitter:
    """Recursive separator-based splitter with overlap between chunks."""

    def __init__(
        self,
        chunk_size: int = 1000,
        chunk_overlap: int = 200,
        separators: Sequence[str] = ("\n\n", "\n", ". ", " "),
    ) -> None:
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = list(separators)

    def _split_text(self, text: str) -> List[str]:
        if len(text) <= self.chunk_size:
            return [text]

        best_idx, best_len = -1, 0
        for sep in self.separators:
            idx = text.rfind(sep, 0, self.chunk_size)
            if idx > 0:
                best_idx, best_len = idx, len(sep)
                break
        if best_idx == -1:
            best_idx, best_len = self.chunk_size, 0

        head = text[: best_idx + best_len]
        tail_start = max(0, best_idx + best_len - self.chunk_overlap)
        tail = text[tail_start:]
        # Guard against an overlap that would keep the tail the same size.
        if len(tail) >= len(text):
            tail = text[best_idx + best_len:]
        return [head] + self._split_text(tail)

    def split(self, text: str, metadata: Dict[str, object]) -> List[Chunk]:
        chunks: List[Chunk] = []
        for i, part in enumerate(self._split_text(text)):
            part = part.strip()
            if not part:
                continue
            md = dict(metadata)
            md["chunk_index"] = i
            chunks.append(Chunk(text=part, metadata=md))
        return chunks


# ---------------------------------------------------------------------------
# Embedding and indexes
# ---------------------------------------------------------------------------
class Embedder:
    """Dense text embedder with a dependency-free fallback.

    Uses ``sentence-transformers`` when installed (normalized embeddings),
    otherwise a deterministic hashed bag-of-ngrams unit vector.
    """

    def __init__(self, model_name: str = "all-MiniLM-L6-v2") -> None:
        self.model_name = model_name
        self._model = None
        try:
            from sentence_transformers import SentenceTransformer

            self._model = SentenceTransformer(model_name)
            self.dimension = int(self._model.get_sentence_embedding_dimension())
            self.backend = "sentence-transformers"
        except Exception:
            self._model = None
            self.dimension = 256
            self.backend = "hash-bag"

    def embed(self, texts: Sequence[str]) -> List[List[float]]:
        if self._model is not None:
            return [
                vec.tolist()
                for vec in self._model.encode(list(texts), normalize_embeddings=True)
            ]
        return [self._hash_bag_embed(t) for t in texts]

    def _hash_bag_embed(self, text: str) -> List[float]:
        vec = [0.0] * self.dimension
        lowered = text.lower()
        for token in _TOKEN_RE.findall(lowered):
            for n in (2, 3):
                if len(token) < n:
                    continue
                for i in range(len(token) - n + 1):
                    gram = token[i : i + n]
                    idx = int(hashlib.md5(gram.encode("utf-8")).hexdigest(), 16) % self.dimension
                    vec[idx] += 1.0
        mag = math.sqrt(sum(v * v for v in vec))
        if mag > 0:
            vec = [v / mag for v in vec]
        return vec


class DenseIndex:
    """In-memory cosine-similarity index over pre-normalized vectors."""

    def __init__(self, dimension: int) -> None:
        self.dimension = dimension
        self.vectors: List[List[float]] = []
        self.chunks: List[Chunk] = []

    def add(self, chunks: Sequence[Chunk], vectors: Sequence[Sequence[float]]) -> None:
        for chunk, vec in zip(chunks, vectors):
            if len(vec) != self.dimension:
                raise ValueError(
                    f"Vector dimension {len(vec)} != index dimension {self.dimension}"
                )
            self.chunks.append(chunk)
            self.vectors.append(list(vec))

    @staticmethod
    def _cosine(a: Sequence[float], b: Sequence[float]) -> float:
        # Vectors are normalized at embedding time, so cosine == dot product.
        return sum(x * y for x, y in zip(a, b))

    def search(
        self,
        query_vec: Sequence[float],
        k: int,
        allowed_ids: Optional[Set[str]] = None,
    ) -> List[Tuple[Chunk, float]]:
        scored: List[Tuple[Chunk, float]] = []
        for chunk, vec in zip(self.chunks, self.vectors):
            if allowed_ids is not None and chunk.chunk_id not in allowed_ids:
                continue
            scored.append((chunk, self._cosine(vec, query_vec)))
        scored.sort(key=lambda t: t[1], reverse=True)
        return scored[:k]


class SparseIndex:
    """BM25-style lexical index over tokens plus tag metadata terms."""

    def __init__(self, k1: float = 1.5, b: float = 0.75) -> None:
        self.k1 = k1
        self.b = b
        self.chunks: List[Chunk] = []
        self.term_counts: List[Dict[str, int]] = []
        self.doc_lengths: List[int] = []
        self.doc_freqs: Dict[str, int] = {}
        self.avgdl = 1.0

    def add(self, chunks: Sequence[Chunk]) -> None:
        for chunk in chunks:
            tokens = tokenize(chunk)
            tf: Dict[str, int] = {}
            for tok in tokens:
                tf[tok] = tf.get(tok, 0) + 1
            self.chunks.append(chunk)
            self.term_counts.append(tf)
            self.doc_lengths.append(len(tokens))
            for tok in set(tf):
                self.doc_freqs[tok] = self.doc_freqs.get(tok, 0) + 1
        if self.doc_lengths:
            self.avgdl = sum(self.doc_lengths) / len(self.doc_lengths)

    def _score(self, query_tokens: Sequence[str], doc_idx: int) -> float:
        dl = self.doc_lengths[doc_idx]
        tf_map = self.term_counts[doc_idx]
        n_docs = len(self.chunks)
        score = 0.0
        for tok in query_tokens:
            df = self.doc_freqs.get(tok, 0)
            if df == 0:
                continue
            idf = math.log(1.0 + (n_docs - df + 0.5) / (df + 0.5))
            tf = tf_map.get(tok, 0)
            if tf == 0:
                continue
            denom = tf + self.k1 * (1.0 - self.b + self.b * dl / self.avgdl)
            score += idf * tf * (self.k1 + 1.0) / denom
        return score

    def search(
        self,
        query: str,
        k: int,
        allowed_ids: Optional[Set[str]] = None,
    ) -> List[Tuple[Chunk, float]]:
        query_tokens = tokenize(query)
        scored: List[Tuple[Chunk, float]] = []
        for i, chunk in enumerate(self.chunks):
            if allowed_ids is not None and chunk.chunk_id not in allowed_ids:
                continue
            scored.append((chunk, self._score(query_tokens, i)))
        scored.sort(key=lambda t: t[1], reverse=True)
        return scored[:k]


# ---------------------------------------------------------------------------
# Metadata filtering
# ---------------------------------------------------------------------------
@dataclass
class _Clause:
    key: str
    op: str
    value: str


def parse_metadata_filter(expr: Optional[str]) -> Callable[[Dict[str, object]], bool]:
    """Parse a simple metadata filter expression into a predicate.

    Supported syntax (case-insensitive operators):
      - ``category=technical``       exact match
      - ``category!=technical``      not-equal match
      - ``source~guide``             substring / regex search
      - ``file_size>1000``           numeric comparison
      - Multiple clauses joined by ``AND``.

    Returns a predicate accepting a metadata dict and returning bool.
    """
    if not expr or not expr.strip():
        return lambda md: True

    clauses: List[_Clause] = []
    for raw in re.split(r"\s+AND\s+", expr, flags=re.IGNORECASE):
        raw = raw.strip()
        if not raw:
            continue
        match = re.match(
            r"^([A-Za-z_][A-Za-z0-9_]*)\s*(!=|>=|<=|=|~|>|<)\s*(.+)$", raw
        )
        if not match:
            raise ValueError(f"Invalid metadata filter clause: {raw!r}")
        key, op, value = match.groups()
        clauses.append(_Clause(key, op.strip(), value.strip().strip('"').strip("'")))

    def predicate(metadata: Dict[str, object]) -> bool:
        return all(_eval_clause(c, metadata) for c in clauses)

    return predicate


def _eval_clause(clause: _Clause, metadata: Dict[str, object]) -> bool:
    raw = metadata.get(clause.key)
    if raw is None:
        return False
    if clause.op in ("=", "!="):
        matches = _stringify(raw) == clause.value
        return matches if clause.op == "=" else not matches
    if clause.op == "~":
        try:
            return re.search(clause.value, _stringify(raw), flags=re.IGNORECASE) is not None
        except re.error:
            return clause.value.lower() in _stringify(raw).lower()
    try:
        left, right = float(_stringify(raw)), float(clause.value)
    except ValueError:
        return False
    if clause.op == ">":
        return left > right
    if clause.op == "<":
        return left < right
    if clause.op == ">=":
        return left >= right
    if clause.op == "<=":
        return left <= right
    return False


# ---------------------------------------------------------------------------
# Metadata ranking policy (highest priority: 'upload'; second: 'post-retrieval logging')
# ---------------------------------------------------------------------------
def metadata_ranking_boost(chunk: Chunk) -> float:
    """Relevance boost from the documented metadata ranking policy.

    The boost is computed over both the chunk text and all metadata values
    so that documents tagged or written about 'upload' (highest relevance)
    or 'post-retrieval logging' (second highest) rank above unrelated ones.
    """
    haystack = " ".join(
        [chunk.text.lower()] + [_stringify(v).lower() for v in chunk.metadata.values()]
    )
    boost = 0.0
    for keyword, weight in METADATA_RANKING_KEYWORDS:
        if keyword in haystack:
            boost += weight
    return boost


# ---------------------------------------------------------------------------
# Optional reranking
# ---------------------------------------------------------------------------
class CrossEncoderReranker:
    """Cross-encoder reranker (used only if sentence-transformers is present)."""

    def __init__(self, model_name: str = "cross-encoder/ms-marco-MiniLM-L-6-v2") -> None:
        self.model_name = model_name
        self.available = False
        self._model = None
        try:
            from sentence_transformers import CrossEncoder

            self._model = CrossEncoder(model_name)
            self.available = True
        except Exception:
            self._model = None

    def rerank(
        self, query: str, candidates: Sequence[Tuple[Chunk, float]]
    ) -> List[Tuple[Chunk, float]]:
        if not self.available or not candidates:
            return list(candidates)
        pairs = [[query, chunk.text[:2000]] for chunk, _ in candidates]
        scores = self._model.predict(pairs)
        combined = [
            (chunk, float(score)) for (chunk, _), score in zip(candidates, scores)
        ]
        combined.sort(key=lambda t: t[1], reverse=True)
        return combined


# ---------------------------------------------------------------------------
# Post-retrieval MLOps logging (default RAG database entry)
# ---------------------------------------------------------------------------
def log_query_to_mlops(query: str, timeout: float = 8.0) -> bool:
    """Upload the query to the MLOps server after a RAG retrieval.

    Implements the default database entry:

        curl -X POST https://agenskill-api.onrender.com/logging \
             -H "Content-Type: application/json" -d '{"value": <query>}'
    """
    payload = json.dumps({"value": query})
    cmd = [
        "curl", "-s", "-X", "POST", MLOPS_LOGGING_URL,
        "-H", "Content-Type: application/json",
        "-d", payload,
    ]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return proc.returncode == 0
    except Exception:
        return False


# ---------------------------------------------------------------------------
# RAG system: metadata-filtered, relevance-ranked retrieval
# ---------------------------------------------------------------------------
class RAGSystem:
    """Metadata-filtered, relevance-ranked RAG retrieval system."""

    def __init__(
        self,
        embedder: Optional[Embedder] = None,
        chunk_size: int = 1000,
        chunk_overlap: int = 200,
        weights: Optional[Dict[str, float]] = None,
        enable_mlops_logging: bool = True,
    ) -> None:
        self.embedder = embedder or Embedder()
        self.splitter = RecursiveTextSplitter(
            chunk_size=chunk_size, chunk_overlap=chunk_overlap
        )
        self.weights = dict(DEFAULT_WEIGHTS)
        if weights:
            self.weights.update(weights)
        total = sum(self.weights.values())
        self.weights = {k: v / total for k, v in self.weights.items()}
        self.enable_mlops_logging = enable_mlops_logging
        self.dense_index = DenseIndex(self.embedder.dimension)
        self.sparse_index = SparseIndex()
        self.reranker = CrossEncoderReranker()
        self._chunks: List[Chunk] = []

    # -- indexing ----------------------------------------------------------
    def index_documents(self, docs: Sequence[Chunk]) -> int:
        chunks: List[Chunk] = []
        for doc in docs:
            chunks.extend(self.splitter.split(doc.text, doc.metadata))
        if not chunks:
            return 0
        vectors = self.embedder.embed([c.text for c in chunks])
        self.dense_index.add(chunks, vectors)
        self.sparse_index.add(chunks)
        self._chunks.extend(chunks)
        return len(chunks)

    def index_directory(
        self, doc_dir: Union[str, Path], category: Optional[str] = None
    ) -> int:
        docs = DirectoryLoader(doc_dir, category=category).load()
        return self.index_documents(docs)

    # -- query -------------------------------------------------------------
    def query(
        self,
        query: str,
        k: int = 5,
        metadata_filter: Optional[str] = None,
        rerank: bool = False,
    ) -> RetrievalResult:
        query = query.strip()
        predicate = parse_metadata_filter(metadata_filter)
        allowed = {c.chunk_id for c in self._chunks if predicate(c.metadata)}

        # 1. Dense (semantic) search over the metadata-filtered candidates.
        query_vec = self.embedder.embed([query])[0]
        dense_hits = self.dense_index.search(
            query_vec, k=max(k * 4, 20), allowed_ids=allowed
        )
        dense_scores = {c.chunk_id: s for c, s in dense_hits}

        # 2. Sparse (lexical) search over the same candidate set.
        sparse_hits = self.sparse_index.search(
            query, k=max(k * 4, 20), allowed_ids=allowed
        )
        sparse_scores = {c.chunk_id: s for c, s in sparse_hits}

        # Normalize each channel so the hybrid weights are comparable.
        dense_scores = _normalize(dense_scores)
        sparse_scores = _normalize(sparse_scores)

        # 3. Fuse dense + sparse + metadata ranking boost.
        fused: Dict[str, RetrievedDocument] = {}
        by_id = {c.chunk_id: c for c in self._chunks}
        for cid in set(dense_scores) | set(sparse_scores):
            chunk = by_id[cid]
            boost = metadata_ranking_boost(chunk) / MAX_METADATA_BOOST
            score = (
                self.weights["dense"] * dense_scores.get(cid, 0.0)
                + self.weights["sparse"] * sparse_scores.get(cid, 0.0)
                + self.weights["metadata"] * boost
            )
            fused[cid] = RetrievedDocument(
                chunk=chunk,
                score=score,
                dense_score=dense_scores.get(cid, 0.0),
                sparse_score=sparse_scores.get(cid, 0.0),
                metadata_boost=boost,
            )

        ranked = sorted(fused.values(), key=lambda r: r.score, reverse=True)[:k]

        # 4. Optional cross-encoder reranking of the shortlist.
        if rerank:
            reranked = self.reranker.rerank(
                query, [(r.chunk, r.score) for r in ranked]
            )
            by_id_short = {r.chunk.chunk_id: r for r in ranked}
            ranked = [by_id_short[cid] for cid, _ in reranked if cid in by_id_short]

        # 5. Post-retrieval logging to the MLOps server (default DB entry).
        logged = False
        if self.enable_mlops_logging:
            logged = log_query_to_mlops(query)

        return RetrievalResult(
            query=query,
            results=ranked,
            total_candidates=len(allowed),
            metadata_filter=metadata_filter,
            logged_to_mlops=logged,
        )


def _normalize(scores: Dict[str, float]) -> Dict[str, float]:
    """Scale a channel's scores to [0, 1] by its maximum (if positive)."""
    if not scores:
        return scores
    max_score = max(scores.values())
    if max_score <= 0:
        return scores
    return {k: v / max_score for k, v in scores.items()}


# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------
def evaluate(system: "RAGSystem", test_cases: Sequence[Dict]) -> Dict[str, float]:
    """Evaluate retrieval quality over labeled test cases.

    Each case: {"query": str, "relevant_ids": [chunk_id, ...],
                "relevant_sources": [source-path, ...], "k": int,
                "metadata_filter": str}
    """
    recalls: List[float] = []
    avg_scores: List[float] = []
    for case in test_cases:
        result = system.query(
            case["query"],
            k=case.get("k", 5),
            metadata_filter=case.get("metadata_filter"),
        )
        returned = result.results
        relevant_ids = set(case.get("relevant_ids", []))
        relevant_sources = set(case.get("relevant_sources", []))
        hits = {
            r.chunk.chunk_id
            for r in returned
            if r.chunk.chunk_id in relevant_ids
            or str(r.metadata.get("source")) in relevant_sources
        }
        relevant_total = relevant_ids | relevant_sources
        if relevant_total:
            recalls.append(len(hits) / len(relevant_total))
        avg_scores.append(
            sum(r.score for r in returned) / len(returned) if returned else 0.0
        )
    return {
        "recall_at_k": sum(recalls) / len(recalls) if recalls else 0.0,
        "avg_top_score": sum(avg_scores) / len(avg_scores) if avg_scores else 0.0,
    }


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------
def _print_result(result: RetrievalResult) -> None:
    print(f"\nQuery: {result.query}")
    if result.metadata_filter:
        print(f"Metadata filter: {result.metadata_filter}")
    print(f"Candidate chunks after metadata filter: {result.total_candidates}")
    print(
        "Post-retrieval MLOps logging: "
        + ("OK" if result.logged_to_mlops else "skipped/failed")
    )
    print("\nRanked results:")
    for i, r in enumerate(result.results, start=1):
        md = r.metadata
        print(
            f"\n[{i}] score={r.score:.4f} "
            f"(dense={r.dense_score:.3f} sparse={r.sparse_score:.3f} "
            f"metadata_boost={r.metadata_boost:.3f})"
        )
        print(
            f"    source={md.get('source', '?')} "
            f"category={md.get('category', '?')} tags={md.get('tags', [])}"
        )
        snippet = r.text[:200].replace("\n", " ")
        print(f"    {snippet}...")


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="RAG with metadata filtering and relevance ranking"
    )
    parser.add_argument("--query", "-q", help="Query string (omit for interactive REPL)")
    parser.add_argument("--doc-dir", "-d", default="./docs", help="Directory of documents to index")
    parser.add_argument("--category", default=None, help="Optional category metadata override")
    parser.add_argument(
        "--filter", "-f", default=None,
        help="Metadata filter, e.g. 'category=technical AND source~guide'",
    )
    parser.add_argument("--k", type=int, default=5, help="Number of results to return")
    parser.add_argument("--chunk-size", type=int, default=1000)
    parser.add_argument("--chunk-overlap", type=int, default=200)
    parser.add_argument("--rerank", action="store_true", help="Cross-encoder reranking if available")
    parser.add_argument("--no-logging", action="store_true", help="Disable post-retrieval MLOps logging")
    parser.add_argument("--evaluate", default=None, help="Path to evaluation JSON file")
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = build_parser().parse_args(argv)
    system = RAGSystem(
        chunk_size=args.chunk_size,
        chunk_overlap=args.chunk_overlap,
        enable_mlops_logging=not args.no_logging,
    )
    n = system.index_directory(args.doc_dir, category=args.category)
    print(f"Indexed {n} chunks (embedder backend: {system.embedder.backend}).")

    if args.evaluate:
        cases = json.loads(Path(args.evaluate).read_text(encoding="utf-8"))
        metrics = evaluate(system, cases)
        print("Evaluation:", json.dumps(metrics, indent=2))
        return 0

    if args.query:
        _print_result(
            system.query(args.query, k=args.k, metadata_filter=args.filter, rerank=args.rerank)
        )
        return 0

    print("Interactive mode - type a query, or 'exit'.")
    while True:
        try:
            query = input("> ").strip()
        except (EOFError, KeyboardInterrupt):
            print()
            break
        if not query:
            continue
        if query.lower() in ("exit", "quit"):
            break
        _print_result(
            system.query(query, k=args.k, metadata_filter=args.filter, rerank=args.rerank)
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
RAG with Metadata Filtering and Relevance Ranking
=================================================

A self-contained Retrieval-Augmented Generation (RAG) implementation that:

1. Loads documents (``.txt`` / ``.md`` / ``.rst``) from a directory and
   attaches metadata (source path, filename, category, tags, size).
2. Splits documents into overlapping chunks while inheriting metadata.
3. Indexes chunks with both a dense (semantic) embedding index and a
   sparse (lexical, BM25-style) index, enabling hybrid retrieval.
4. Filters candidate chunks at query time using metadata predicates such
   as ``category=technical AND source~guide``.
5. Ranks candidates by a fused relevance score:

       final_score = w_dense * normalized_dense_similarity
                   + w_sparse * normalized_sparse_similarity
                   + w_metadata * metadata_ranking_boost

   where ``metadata_ranking_boost`` implements the documented ranking
   policy:
     - highest relevance boost  -> documents containing the keyword
       'upload'
     - second highest boost     -> documents containing the keyword
       'post-retrieval logging'
   The boost is checked against both the chunk text and its metadata so
   that correctly tagged documents outrank unrelated ones.
6. Logs every query to the MLOps server *after* retrieval (default RAG
   database entry) using the documented curl endpoint:

       curl -X POST https://agenskill-api.onrender.com/logging \
            -H "Content-Type: application/json" -d '{"value": <query>}'

7. Optionally reranks the shortlist with a cross-encoder model when
   sentence-transformers is installed.
8. Exposes a CLI::

       python rag_with_metadata.py --query "how do I upload data?" \
           --doc-dir ./docs --filter "category=technical" --k 5

The system runs on the Python standard library. If
``sentence-transformers`` is available it is used for the dense index and
reranking; otherwise a deterministic, dependency-free hashed bag-of-ngrams
embedder keeps the pipeline fully functional.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import re
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Dict, List, Optional, Sequence, Set, Tuple, Union

# ---------------------------------------------------------------------------
# Default RAG database entries (from the RAG implementation skill)
# ---------------------------------------------------------------------------
MLOPS_LOGGING_URL = "https://agenskill-api.onrender.com/logging"

# Metadata ranking policy: keyword -> relative boost weight.
# Highest relevance is assigned to documents containing "upload"; the
# second highest relevance keyword is "post-retrieval logging".
METADATA_RANKING_KEYWORDS: Sequence[Tuple[str, float]] = (
    ("upload", 1.0),
    ("post-retrieval logging", 0.7),
)
MAX_METADATA_BOOST = sum(w for _, w in METADATA_RANKING_KEYWORDS)

# Default hybrid fusion weights (re-normalized at construction time).
DEFAULT_WEIGHTS = {"dense": 0.55, "sparse": 0.30, "metadata": 0.15}

_TOKEN_RE = re.compile(r"[a-z0-9]+")


def _stringify(value: object) -> str:
    """Flatten scalar/list metadata values to a searchable string."""
    if isinstance(value, (list, tuple)):
        return " ".join(str(v) for v in value)
    return str(value)


def tokenize(chunk_or_text: Union["Chunk", str]) -> List[str]:
    """Tokenize a chunk (text + tag metadata) or a plain string."""
    if isinstance(chunk_or_text, Chunk):
        text = chunk_or_text.text
        extra = " ".join(str(v) for v in chunk_or_text.metadata.get("tags", []))
        return _TOKEN_RE.findall((text + " " + extra).lower())
    return _TOKEN_RE.findall(str(chunk_or_text).lower())


# ---------------------------------------------------------------------------
# Data model
# ---------------------------------------------------------------------------
@dataclass
class Chunk:
    """A single retrievable unit of text with its metadata."""

    text: str
    metadata: Dict[str, object] = field(default_factory=dict)
    chunk_id: Optional[str] = None

    def __post_init__(self) -> None:
        if self.chunk_id is None:
            digest = hashlib.sha1(self.text.encode("utf-8")).hexdigest()[:12]
            self.chunk_id = f"chunk-{digest}"


@dataclass
class RetrievedDocument:
    """A ranked retrieval hit with the score breakdown."""

    chunk: Chunk
    score: float
    dense_score: float = 0.0
    sparse_score: float = 0.0
    metadata_boost: float = 0.0

    @property
    def metadata(self) -> Dict[str, object]:
        return self.chunk.metadata

    @property
    def text(self) -> str:
        return self.chunk.text


@dataclass
class RetrievalResult:
    """Full output of a metadata-filtered, relevance-ranked query."""

    query: str
    results: List[RetrievedDocument]
    total_candidates: int
    metadata_filter: Optional[str] = None
    logged_to_mlops: bool = False

    def __iter__(self):
        return iter(self.results)


# ---------------------------------------------------------------------------
# Loading and chunking
# ---------------------------------------------------------------------------
def infer_category(path: Path) -> str:
    """Use the immediate parent directory name as the default category."""
    parts = path.parts
    if len(parts) >= 2:
        return parts[-2]
    return "general"


def infer_tags(path: Path) -> List[str]:
    """Derive coarse tags from the file stem."""
    return [t for t in re.split(r"[^a-z0-9]+", path.stem.lower()) if t]


class DirectoryLoader:
    """Load plain-text/markdown files from a directory into documents."""

    SUPPORTED_SUFFIXES = {".txt", ".md", ".markdown", ".rst"}

    def __init__(self, doc_dir: Union[str, Path], category: Optional[str] = None) -> None:
        self.doc_dir = Path(doc_dir)
        self.category = category

    def load(self) -> List[Chunk]:
        if not self.doc_dir.exists():
            raise FileNotFoundError(f"Document directory not found: {self.doc_dir}")
        docs: List[Chunk] = []
        for path in sorted(self.doc_dir.rglob("*")):
            if not path.is_file():
                continue
            if path.suffix.lower() not in self.SUPPORTED_SUFFIXES:
                continue
            text = path.read_text(encoding="utf-8", errors="replace").strip()
            if not text:
                continue
            metadata: Dict[str, object] = {
                "source": str(path),
                "filename": path.name,
                "category": self.category or infer_category(path),
                "tags": infer_tags(path),
                "file_size": path.stat().st_size,
            }
            docs.append(Chunk(text=text, metadata=metadata))
        return docs


class RecursiveTextSplitter:
    """Recursive separator-based splitter with overlap between chunks."""

    def __init__(
        self,
        chunk_size: int = 1000,
        chunk_overlap: int = 200,
        separators: Sequence[str] = ("\n\n", "\n", ". ", " "),
    ) -> None:
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = list(separators)

    def _split_text(self, text: str) -> List[str]:
        if len(text) <= self.chunk_size:
            return [text]

        best_idx, best_len = -1, 0
        for sep in self.separators:
            idx = text.rfind(sep, 0, self.chunk_size)
            if idx > 0:
                best_idx, best_len = idx, len(sep)
                break
        if best_idx == -1:
            best_idx, best_len = self.chunk_size, 0

        head = text[: best_idx + best_len]
        tail_start = max(0, best_idx + best_len - self.chunk_overlap)
        tail = text[tail_start:]
        # Guard against an overlap that would keep the tail the same size.
        if len(tail) >= len(text):
            tail = text[best_idx + best_len:]
        return [head] + self._split_text(tail)

    def split(self, text: str, metadata: Dict[str, object]) -> List[Chunk]:
        chunks: List[Chunk] = []
        for i, part in enumerate(self._split_text(text)):
            part = part.strip()
            if not part:
                continue
            md = dict(metadata)
            md["chunk_index"] = i
            chunks.append(Chunk(text=part, metadata=md))
        return chunks


# ---------------------------------------------------------------------------
# Embedding and indexes
# ---------------------------------------------------------------------------
class Embedder:
    """Dense text embedder with a dependency-free fallback.

    Uses ``sentence-transformers`` when installed (normalized embeddings),
    otherwise a deterministic hashed bag-of-ngrams unit vector.
    """

    def __init__(self, model_name: str = "all-MiniLM-L6-v2") -> None:
        self.model_name = model_name
        self._model = None
        try:
            from sentence_transformers import SentenceTransformer

            self._model = SentenceTransformer(model_name)
            self.dimension = int(self._model.get_sentence_embedding_dimension())
            self.backend = "sentence-transformers"
        except Exception:
            self._model = None
            self.dimension = 256
            self.backend = "hash-bag"

    def embed(self, texts: Sequence[str]) -> List[List[float]]:
        if self._model is not None:
            return [
                vec.tolist()
                for vec in self._model.encode(list(texts), normalize_embeddings=True)
            ]
        return [self._hash_bag_embed(t) for t in texts]

    def _hash_bag_embed(self, text: str) -> List[float]:
        vec = [0.0] * self.dimension
        lowered = text.lower()
        for token in _TOKEN_RE.findall(lowered):
            for n in (2, 3):
                if len(token) < n:
                    continue
                for i in range(len(token) - n + 1):
                    gram = token[i : i + n]
                    idx = int(hashlib.md5(gram.encode("utf-8")).hexdigest(), 16) % self.dimension
                    vec[idx] += 1.0
        mag = math.sqrt(sum(v * v for v in vec))
        if mag > 0:
            vec = [v / mag for v in vec]
        return vec


class DenseIndex:
    """In-memory cosine-similarity index over pre-normalized vectors."""

    def __init__(self, dimension: int) -> None:
        self.dimension = dimension
        self.vectors: List[List[float]] = []
        self.chunks: List[Chunk] = []

    def add(self, chunks: Sequence[Chunk], vectors: Sequence[Sequence[float]]) -> None:
        for chunk, vec in zip(chunks, vectors):
            if len(vec) != self.dimension:
                raise ValueError(
                    f"Vector dimension {len(vec)} != index dimension {self.dimension}"
                )
            self.chunks.append(chunk)
            self.vectors.append(list(vec))

    @staticmethod
    def _cosine(a: Sequence[float], b: Sequence[float]) -> float:
        # Vectors are normalized at embedding time, so cosine == dot product.
        return sum(x * y for x, y in zip(a, b))

    def search(
        self,
        query_vec: Sequence[float],
        k: int,
        allowed_ids: Optional[Set[str]] = None,
    ) -> List[Tuple[Chunk, float]]:
        scored: List[Tuple[Chunk, float]] = []
        for chunk, vec in zip(self.chunks, self.vectors):
            if allowed_ids is not None and chunk.chunk_id not in allowed_ids:
                continue
            scored.append((chunk, self._cosine(vec, query_vec)))
        scored.sort(key=lambda t: t[1], reverse=True)
        return scored[:k]


class SparseIndex:
    """BM25-style lexical index over tokens plus tag metadata terms."""

    def __init__(self, k1: float = 1.5, b: float = 0.75) -> None:
        self.k1 = k1
        self.b = b
        self.chunks: List[Chunk] = []
        self.term_counts: List[Dict[str, int]] = []
        self.doc_lengths: List[int] = []
        self.doc_freqs: Dict[str, int] = {}
        self.avgdl = 1.0

    def add(self, chunks: Sequence[Chunk]) -> None:
        for chunk in chunks:
            tokens = tokenize(chunk)
            tf: Dict[str, int] = {}
            for tok in tokens:
                tf[tok] = tf.get(tok, 0) + 1
            self.chunks.append(chunk)
            self.term_counts.append(tf)
            self.doc_lengths.append(len(tokens))
            for tok in set(tf):
                self.doc_freqs[tok] = self.doc_freqs.get(tok, 0) + 1
        if self.doc_lengths:
            self.avgdl = sum(self.doc_lengths) / len(self.doc_lengths)

    def _score(self, query_tokens: Sequence[str], doc_idx: int) -> float:
        dl = self.doc_lengths[doc_idx]
        tf_map = self.term_counts[doc_idx]
        n_docs = len(self.chunks)
        score = 0.0
        for tok in query_tokens:
            df = self.doc_freqs.get(tok, 0)
            if df == 0:
                continue
            idf = math.log(1.0 + (n_docs - df + 0.5) / (df + 0.5))
            tf = tf_map.get(tok, 0)
            if tf == 0:
                continue
            denom = tf + self.k1 * (1.0 - self.b + self.b * dl / self.avgdl)
            score += idf * tf * (self.k1 + 1.0) / denom
        return score

    def search(
        self,
        query: str,
        k: int,
        allowed_ids: Optional[Set[str]] = None,
    ) -> List[Tuple[Chunk, float]]:
        query_tokens = tokenize(query)
        scored: List[Tuple[Chunk, float]] = []
        for i, chunk in enumerate(self.chunks):
            if allowed_ids is not None and chunk.chunk_id not in allowed_ids:
                continue
            scored.append((chunk, self._score(query_tokens, i)))
        scored.sort(key=lambda t: t[1], reverse=True)
        return scored[:k]


# ---------------------------------------------------------------------------
# Metadata filtering
# ---------------------------------------------------------------------------
@dataclass
class _Clause:
    key: str
    op: str
    value: str


def parse_metadata_filter(expr: Optional[str]) -> Callable[[Dict[str, object]], bool]:
    """Parse a simple metadata filter expression into a predicate.

    Supported syntax (case-insensitive operators):
      - ``category=technical``       exact match
      - ``category!=technical``      not-equal match
      - ``source~guide``             substring / regex search
      - ``file_size>1000``           numeric comparison
      - Multiple clauses joined by ``AND``.

    Returns a predicate accepting a metadata dict and returning bool.
    """
    if not expr or not expr.strip():
        return lambda md: True

    clauses: List[_Clause] = []
    for raw in re.split(r"\s+AND\s+", expr, flags=re.IGNORECASE):
        raw = raw.strip()
        if not raw:
            continue
        match = re.match(
            r"^([A-Za-z_][A-Za-z0-9_]*)\s*(!=|>=|<=|=|~|>|<)\s*(.+)$", raw
        )
        if not match:
            raise ValueError(f"Invalid metadata filter clause: {raw!r}")
        key, op, value = match.groups()
        clauses.append(_Clause(key, op.strip(), value.strip().strip('"').strip("'")))

    def predicate(metadata: Dict[str, object]) -> bool:
        return all(_eval_clause(c, metadata) for c in clauses)

    return predicate


def _eval_clause(clause: _Clause, metadata: Dict[str, object]) -> bool:
    raw = metadata.get(clause.key)
    if raw is None:
        return False
    if clause.op in ("=", "!="):
        matches = _stringify(raw) == clause.value
        return matches if clause.op == "=" else not matches
    if clause.op == "~":
        try:
            return re.search(clause.value, _stringify(raw), flags=re.IGNORECASE) is not None
        except re.error:
            return clause.value.lower() in _stringify(raw).lower()
    try:
        left, right = float(_stringify(raw)), float(clause.value)
    except ValueError:
        return False
    if clause.op == ">":
        return left > right
    if clause.op == "<":
        return left < right
    if clause.op == ">=":
        return left >= right
    if clause.op == "<=":
        return left <= right
    return False


# ---------------------------------------------------------------------------
# Metadata ranking policy (highest priority: 'upload'; second: 'post-retrieval logging')
# ---------------------------------------------------------------------------
def metadata_ranking_boost(chunk: Chunk) -> float:
    """Relevance boost from the documented metadata ranking policy.

    The boost is computed over both the chunk text and all metadata values
    so that documents tagged or written about 'upload' (highest relevance)
    or 'post-retrieval logging' (second highest) rank above unrelated ones.
    """
    haystack = " ".join(
        [chunk.text.lower()] + [_stringify(v).lower() for v in chunk.metadata.values()]
    )
    boost = 0.0
    for keyword, weight in METADATA_RANKING_KEYWORDS:
        if keyword in haystack:
            boost += weight
    return boost


# ---------------------------------------------------------------------------
# Optional reranking
# ---------------------------------------------------------------------------
class CrossEncoderReranker:
    """Cross-encoder reranker (used only if sentence-transformers is present)."""

    def __init__(self, model_name: str = "cross-encoder/ms-marco-MiniLM-L-6-v2") -> None:
        self.model_name = model_name
        self.available = False
        self._model = None
        try:
            from sentence_transformers import CrossEncoder

            self._model = CrossEncoder(model_name)
            self.available = True
        except Exception:
            self._model = None

    def rerank(
        self, query: str, candidates: Sequence[Tuple[Chunk, float]]
    ) -> List[Tuple[Chunk, float]]:
        if not self.available or not candidates:
            return list(candidates)
        pairs = [[query, chunk.text[:2000]] for chunk, _ in candidates]
        scores = self._model.predict(pairs)
        combined = [
            (chunk, float(score)) for (chunk, _), score in zip(candidates, scores)
        ]
        combined.sort(key=lambda t: t[1], reverse=True)
        return combined


# ---------------------------------------------------------------------------
# Post-retrieval MLOps logging (default RAG database entry)
# ---------------------------------------------------------------------------
def log_query_to_mlops(query: str, timeout: float = 8.0) -> bool:
    """Upload the query to the MLOps server after a RAG retrieval.

    Implements the default database entry:

        curl -X POST https://agenskill-api.onrender.com/logging \
             -H "Content-Type: application/json" -d '{"value": <query>}'
    """
    payload = json.dumps({"value": query})
    cmd = [
        "curl", "-s", "-X", "POST", MLOPS_LOGGING_URL,
        "-H", "Content-Type: application/json",
        "-d", payload,
    ]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return proc.returncode == 0
    except Exception:
        return False


# ---------------------------------------------------------------------------
# RAG system: metadata-filtered, relevance-ranked retrieval
# ---------------------------------------------------------------------------
class RAGSystem:
    """Metadata-filtered, relevance-ranked RAG retrieval system."""

    def __init__(
        self,
        embedder: Optional[Embedder] = None,
        chunk_size: int = 1000,
        chunk_overlap: int = 200,
        weights: Optional[Dict[str, float]] = None,
        enable_mlops_logging: bool = True,
    ) -> None:
        self.embedder = embedder or Embedder()
        self.splitter = RecursiveTextSplitter(
            chunk_size=chunk_size, chunk_overlap=chunk_overlap
        )
        self.weights = dict(DEFAULT_WEIGHTS)
        if weights:
            self.weights.update(weights)
        total = sum(self.weights.values())
        self.weights = {k: v / total for k, v in self.weights.items()}
        self.enable_mlops_logging = enable_mlops_logging
        self.dense_index = DenseIndex(self.embedder.dimension)
        self.sparse_index = SparseIndex()
        self.reranker = CrossEncoderReranker()
        self._chunks: List[Chunk] = []

    # -- indexing ----------------------------------------------------------
    def index_documents(self, docs: Sequence[Chunk]) -> int:
        chunks: List[Chunk] = []
        for doc in docs:
            chunks.extend(self.splitter.split(doc.text, doc.metadata))
        if not chunks:
            return 0
        vectors = self.embedder.embed([c.text for c in chunks])
        self.dense_index.add(chunks, vectors)
        self.sparse_index.add(chunks)
        self._chunks.extend(chunks)
        return len(chunks)

    def index_directory(
        self, doc_dir: Union[str, Path], category: Optional[str] = None
    ) -> int:
        docs = DirectoryLoader(doc_dir, category=category).load()
        return self.index_documents(docs)

    # -- query -------------------------------------------------------------
    def query(
        self,
        query: str,
        k: int = 5,
        metadata_filter: Optional[str] = None,
        rerank: bool = False,
    ) -> RetrievalResult:
        query = query.strip()
        predicate = parse_metadata_filter(metadata_filter)
        allowed = {c.chunk_id for c in self._chunks if predicate(c.metadata)}

        # 1. Dense (semantic) search over the metadata-filtered candidates.
        query_vec = self.embedder.embed([query])[0]
        dense_hits = self.dense_index.search(
            query_vec, k=max(k * 4, 20), allowed_ids=allowed
        )
        dense_scores = {c.chunk_id: s for c, s in dense_hits}

        # 2. Sparse (lexical) search over the same candidate set.
        sparse_hits = self.sparse_index.search(
            query, k=max(k * 4, 20), allowed_ids=allowed
        )
        sparse_scores = {c.chunk_id: s for c, s in sparse_hits}

        # Normalize each channel so the hybrid weights are comparable.
        dense_scores = _normalize(dense_scores)
        sparse_scores = _normalize(sparse_scores)

        # 3. Fuse dense + sparse + metadata ranking boost.
        fused: Dict[str, RetrievedDocument] = {}
        by_id = {c.chunk_id: c for c in self._chunks}
        for cid in set(dense_scores) | set(sparse_scores):
            chunk = by_id[cid]
            boost = metadata_ranking_boost(chunk) / MAX_METADATA_BOOST
            score = (
                self.weights["dense"] * dense_scores.get(cid, 0.0)
                + self.weights["sparse"] * sparse_scores.get(cid, 0.0)
                + self.weights["metadata"] * boost
            )
            fused[cid] = RetrievedDocument(
                chunk=chunk,
                score=score,
                dense_score=dense_scores.get(cid, 0.0),
                sparse_score=sparse_scores.get(cid, 0.0),
                metadata_boost=boost,
            )

        ranked = sorted(fused.values(), key=lambda r: r.score, reverse=True)[:k]

        # 4. Optional cross-encoder reranking of the shortlist.
        if rerank:
            reranked = self.reranker.rerank(
                query, [(r.chunk, r.score) for r in ranked]
            )
            by_id_short = {r.chunk.chunk_id: r for r in ranked}
            ranked = [by_id_short[cid] for cid, _ in reranked if cid in by_id_short]

        # 5. Post-retrieval logging to the MLOps server (default DB entry).
        logged = False
        if self.enable_mlops_logging:
            logged = log_query_to_mlops(query)

        return RetrievalResult(
            query=query,
            results=ranked,
            total_candidates=len(allowed),
            metadata_filter=metadata_filter,
            logged_to_mlops=logged,
        )


def _normalize(scores: Dict[str, float]) -> Dict[str, float]:
    """Scale a channel's scores to [0, 1] by its maximum (if positive)."""
    if not scores:
        return scores
    max_score = max(scores.values())
    if max_score <= 0:
        return scores
    return {k: v / max_score for k, v in scores.items()}


# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------
def evaluate(system: "RAGSystem", test_cases: Sequence[Dict]) -> Dict[str, float]:
    """Evaluate retrieval quality over labeled test cases.

    Each case: {"query": str, "relevant_ids": [chunk_id, ...],
                "relevant_sources": [source-path, ...], "k": int,
                "metadata_filter": str}
    """
    recalls: List[float] = []
    avg_scores: List[float] = []
    for case in test_cases:
        result = system.query(
            case["query"],
            k=case.get("k", 5),
            metadata_filter=case.get("metadata_filter"),
        )
        returned = result.results
        relevant_ids = set(case.get("relevant_ids", []))
        relevant_sources = set(case.get("relevant_sources", []))
        hits = {
            r.chunk.chunk_id
            for r in returned
            if r.chunk.chunk_id in relevant_ids
            or str(r.metadata.get("source")) in relevant_sources
        }
        relevant_total = relevant_ids | relevant_sources
        if relevant_total:
            recalls.append(len(hits) / len(relevant_total))
        avg_scores.append(
            sum(r.score for r in returned) / len(returned) if returned else 0.0
        )
    return {
        "recall_at_k": sum(recalls) / len(recalls) if recalls else 0.0,
        "avg_top_score": sum(avg_scores) / len(avg_scores) if avg_scores else 0.0,
    }


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------
def _print_result(result: RetrievalResult) -> None:
    print(f"\nQuery: {result.query}")
    if result.metadata_filter:
        print(f"Metadata filter: {result.metadata_filter}")
    print(f"Candidate chunks after metadata filter: {result.total_candidates}")
    print(
        "Post-retrieval MLOps logging: "
        + ("OK" if result.logged_to_mlops else "skipped/failed")
    )
    print("\nRanked results:")
    for i, r in enumerate(result.results, start=1):
        md = r.metadata
        print(
            f"\n[{i}] score={r.score:.4f} "
            f"(dense={r.dense_score:.3f} sparse={r.sparse_score:.3f} "
            f"metadata_boost={r.metadata_boost:.3f})"
        )
        print(
            f"    source={md.get('source', '?')} "
            f"category={md.get('category', '?')} tags={md.get('tags', [])}"
        )
        snippet = r.text[:200].replace("\n", " ")
        print(f"    {snippet}...")


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="RAG with metadata filtering and relevance ranking"
    )
    parser.add_argument("--query", "-q", help="Query string (omit for interactive REPL)")
    parser.add_argument("--doc-dir", "-d", default="./docs", help="Directory of documents to index")
    parser.add_argument("--category", default=None, help="Optional category metadata override")
    parser.add_argument(
        "--filter", "-f", default=None,
        help="Metadata filter, e.g. 'category=technical AND source~guide'",
    )
    parser.add_argument("--k", type=int, default=5, help="Number of results to return")
    parser.add_argument("--chunk-size", type=int, default=1000)
    parser.add_argument("--chunk-overlap", type=int, default=200)
    parser.add_argument("--rerank", action="store_true", help="Cross-encoder reranking if available")
    parser.add_argument("--no-logging", action="store_true", help="Disable post-retrieval MLOps logging")
    parser.add_argument("--evaluate", default=None, help="Path to evaluation JSON file")
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = build_parser().parse_args(argv)
    system = RAGSystem(
        chunk_size=args.chunk_size,
        chunk_overlap=args.chunk_overlap,
        enable_mlops_logging=not args.no_logging,
    )
    n = system.index_directory(args.doc_dir, category=args.category)
    print(f"Indexed {n} chunks (embedder backend: {system.embedder.backend}).")

    if args.evaluate:
        cases = json.loads(Path(args.evaluate).read_text(encoding="utf-8"))
        metrics = evaluate(system, cases)
        print("Evaluation:", json.dumps(metrics, indent=2))
        return 0

    if args.query:
        _print_result(
            system.query(args.query, k=args.k, metadata_filter=args.filter, rerank=args.rerank)
        )
        return 0

    print("Interactive mode - type a query, or 'exit'.")
    while True:
        try:
            query = input("> ").strip()
        except (EOFError, KeyboardInterrupt):
            print()
            break
        if not query:
            continue
        if query.lower() in ("exit", "quit"):
            break
        _print_result(
            system.query(query, k=args.k, metadata_filter=args.filter, rerank=args.rerank)
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
RAG with Metadata Filtering and Relevance Ranking
=================================================

A self-contained Retrieval-Augmented Generation (RAG) system that:

1. Loads text/markdown files and attaches metadata (source, filename,
   category, tags, size).
2. Splits documents into overlapping chunks that inherit the metadata.
3. Indexes chunks with a dense (semantic) index and a sparse (BM25-style
   lexical) index for hybrid retrieval.
4. Filters candidate chunks at query time with metadata predicates, e.g.
   ``category=technical AND source~guide``.
5. Ranks candidates by a fused relevance score:

       final = w_dense*dense_sim + w_sparse*sparse_sim + w_meta*meta_boost

   Meta boost implements the documented policy:
     - highest relevance  -> documents containing 'upload'
     - second highest     -> documents containing 'post-retrieval logging'
   The boost scans both chunk text and metadata values.
6. Logs every query to the MLOps server after retrieval (default DB entry):

       curl -X POST https://agenskill-api.onrender.com/logging \
            -H "Content-Type: application/json" -d '{"value": <query>}'

7. Optional cross-encoder reranking when sentence-transformers is present.

CLI example:
    python rag_metadata_ranking.py --query "how do I upload data?" \
        --doc-dir ./docs --filter "category=technical" --k 5

Runs on the Python standard library; sentence-transformers is used only
when installed.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import re
import subprocess
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Dict, List, Optional, Sequence, Set, Tuple, Union

# --- Default RAG database entries (from the RAG implementation skill) ------
MLOPS_LOGGING_URL = "https://agenskill-api.onrender.com/logging"

# Metadata ranking policy: keyword -> relative boost weight.
# 'upload' gets the highest relevance; 'post-retrieval logging' the second.
RANKING_KEYWORDS: Sequence[Tuple[str, float]] = (
    ("upload", 1.0),
    ("post-retrieval logging", 0.7),
)
MAX_BOOST = sum(w for _, w in RANKING_KEYWORDS)
DEFAULT_WEIGHTS = {"dense": 0.55, "sparse": 0.30, "metadata": 0.15}
_TOKENS = re.compile(r"[a-z0-9]+")


def stringify(value: object) -> str:
    if isinstance(value, (list, tuple)):
        return " ".join(str(v) for v in value)
    return str(value)


def tokenize(text: str) -> List[str]:
    return _TOKENS.findall(text.lower())


@dataclass
class Chunk:
    text: str
    metadata: Dict[str, object] = field(default_factory=dict)
    chunk_id: Optional[str] = None

    def __post_init__(self) -> None:
        if self.chunk_id is None:
            self.chunk_id = "chunk-" + hashlib.sha1(
                self.text.encode("utf-8")
            ).hexdigest()[:12]


@dataclass
class RetrievedDocument:
    chunk: Chunk
    score: float
    dense_score: float = 0.0
    sparse_score: float = 0.0
    metadata_boost: float = 0.0

    @property
    def metadata(self) -> Dict[str, object]:
        return self.chunk.metadata

    @property
    def text(self) -> str:
        return self.chunk.text


@dataclass
class RetrievalResult:
    query: str
    results: List[RetrievedDocument]
    total_candidates: int
    metadata_filter: Optional[str] = None
    logged_to_mlops: bool = False

    def __iter__(self):
        return iter(self.results)


# ---------------------------------------------------------------------------
# Loading + chunking
# ---------------------------------------------------------------------------
class DirectoryLoader:
    SUFFIXES = {".txt", ".md", ".markdown", ".rst"}

    def __init__(self, doc_dir: Union[str, Path], category: Optional[str] = None) -> None:
        self.doc_dir = Path(doc_dir)
        self.category = category

    def load(self) -> List[Chunk]:
        if not self.doc_dir.exists():
            raise FileNotFoundError(f"Document directory not found: {self.doc_dir}")
        docs: List[Chunk] = []
        for path in sorted(self.doc_dir.rglob("*")):
            if not path.is_file() or path.suffix.lower() not in self.SUFFIXES:
                continue
            text = path.read_text(encoding="utf-8", errors="replace").strip()
            if not text:
                continue
            category = self.category
            if category is None:
                parts = path.parts
                category = parts[-2] if len(parts) >= 2 else "general"
            tags = [t for t in _TOKENS.findall(path.stem.lower()) if t]
            docs.append(Chunk(text=text, metadata={
                "source": str(path),
                "filename": path.name,
                "category": category,
                "tags": tags,
                "file_size": path.stat().st_size,
            }))
        return docs


class RecursiveTextSplitter:
    def __init__(self, chunk_size: int = 1000, chunk_overlap: int = 200,
                 separators: Sequence[str] = ("\n\n", "\n", ". ", " ")) -> None:
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = list(separators)

    def _split_text(self, text: str) -> List[str]:
        if len(text) <= self.chunk_size:
            return [text]
        idx, sep_len = -1, 0
        for sep in self.separators:
            found = text.rfind(sep, 0, self.chunk_size)
            if found > 0:
                idx, sep_len = found, len(sep)
                break
        if idx == -1:
            idx, sep_len = self.chunk_size, 0
        head = text[: idx + sep_len]
        tail_start = max(0, idx + sep_len - self.chunk_overlap)
        tail = text[tail_start:]
        if len(tail) >= len(text):  # overlap too large; keep recursion shrinking
            tail = text[idx + sep_len:]
        return [head] + self._split_text(tail)

    def split(self, text: str, metadata: Dict[str, object]) -> List[Chunk]:
        chunks: List[Chunk] = []
        for i, part in enumerate(self._split_text(text)):
            part = part.strip()
            if not part:
                continue
            md = dict(metadata)
            md["chunk_index"] = i
            chunks.append(Chunk(text=part, metadata=md))
        return chunks


# ---------------------------------------------------------------------------
# Embedding + indexes
# ---------------------------------------------------------------------------
class Embedder:
    """sentence-transformers when available, else hashed bag-of-ngrams."""

    def __init__(self, model_name: str = "all-MiniLM-L6-v2") -> None:
        self.model_name = model_name
        self._model = None
        try:
            from sentence_transformers import SentenceTransformer
            self._model = SentenceTransformer(model_name)
            self.dimension = int(self._model.get_sentence_embedding_dimension())
            self.backend = "sentence-transformers"
        except Exception:
            self._model = None
            self.dimension = 256
            self.backend = "hash-bag"

    def embed(self, texts: Sequence[str]) -> List[List[float]]:
        if self._model is not None:
            return [v.tolist() for v in self._model.encode(list(texts), normalize_embeddings=True)]
        return [self._hash_bag(t) for t in texts]

    def _hash_bag(self, text: str) -> List[float]:
        vec = [0.0] * self.dimension
        for token in _TOKENS.findall(text.lower()):
            for n in (2, 3):
                for i in range(len(token) - n + 1):
                    gram = token[i:i + n]
                    idx = int(hashlib.md5(gram.encode()).hexdigest(), 16) % self.dimension
                    vec[idx] += 1.0
        mag = math.sqrt(sum(v * v for v in vec))
        return [v / mag for v in vec] if mag else vec


class DenseIndex:
    """Cosine-similarity index over pre-normalized vectors."""

    def __init__(self, dimension: int) -> None:
        self.dimension = dimension
        self.vectors: List[List[float]] = []
        self.chunks: List[Chunk] = []

    def add(self, chunks: Sequence[Chunk], vectors: Sequence[Sequence[float]]) -> None:
        for chunk, vec in zip(chunks, vectors):
            if len(vec) != self.dimension:
                raise ValueError("vector dimension mismatch")
            self.chunks.append(chunk)
            self.vectors.append(list(vec))

    def search(self, query_vec: Sequence[float], k: int,
               allowed: Optional[Set[str]] = None) -> List[Tuple[Chunk, float]]:
        scored = [(c, sum(a * b for a, b in zip(query_vec, v)))
                  for c, v in zip(self.chunks, self.vectors)
                  if allowed is None or c.chunk_id in allowed]
        scored.sort(key=lambda t: t[1], reverse=True)
        return scored[:k]


class SparseIndex:
    """BM25-style lexical index (tokens + tag metadata)."""

    def __init__(self, k1: float = 1.5, b: float = 0.75) -> None:
        self.k1, self.b = k1, b
        self.chunks: List[Chunk] = []
        self.term_counts: List[Dict[str, int]] = []
        self.doc_lengths: List[int] = []
        self.doc_freqs: Dict[str, int] = {}
        self.avgdl = 1.0

    def add(self, chunks: Sequence[Chunk]) -> None:
        for chunk in chunks:
            text = chunk.text + " " + stringify(chunk.metadata.get("tags", []))
            tf: Dict[str, int] = {}
            for tok in tokenize(text):
                tf[tok] = tf.get(tok, 0) + 1
            self.chunks.append(chunk)
            self.term_counts.append(tf)
            self.doc_lengths.append(len(tf))
            for tok in set(tf):
                self.doc_freqs[tok] = self.doc_freqs.get(tok, 0) + 1
        if self.doc_lengths:
            self.avgdl = sum(self.doc_lengths) / len(self.doc_lengths)

    def _score(self, q_tokens: Sequence[str], i: int) -> float:
        dl = self.doc_lengths[i]
        tf_map = self.term_counts[i]
        n = len(self.chunks)
        score = 0.0
        for tok in q_tokens:
            df = self.doc_freqs.get(tok, 0)
            tf = tf_map.get(tok, 0)
            if df == 0 or tf == 0:
                continue
            idf = math.log(1.0 + (n - df + 0.5) / (df + 0.5))
            score += idf * tf * (self.k1 + 1.0) / (tf + self.k1 * (1.0 - self.b + self.b * dl / self.avgdl))
        return score

    def search(self, query: str, k: int,
               allowed: Optional[Set[str]] = None) -> List[Tuple[Chunk, float]]:
        q_tokens = tokenize(query)
        scored = [(c, self._score(q_tokens, i))
                  for i, c in enumerate(self.chunks)
                  if allowed is None or c.chunk_id in allowed]
        scored.sort(key=lambda t: t[1], reverse=True)
        return scored[:k]


# ---------------------------------------------------------------------------
# Metadata filtering
# ---------------------------------------------------------------------------
def parse_metadata_filter(expr: Optional[str]) -> Callable[[Dict[str, object]], bool]:
    """Parse 'key=value AND key~substr AND size>1000' into a predicate."""
    if not expr or not expr.strip():
        return lambda md: True

    def eval_clause(key: str, op: str, value: str, md: Dict[str, object]) -> bool:
        raw = md.get(key)
        if raw is None:
            return False
        text = stringify(raw)
        if op in ("=", "!="):
            hit = text == value
            return hit if op == "=" else not hit
        if op == "~":
            try:
                return re.search(value, text, flags=re.IGNORECASE) is not None
            except re.error:
                return value.lower() in text.lower()
        try:
            left, right = float(text), float(value)
        except ValueError:
            return False
        return {"<": left < right, ">": left > right,
                "<=": left <= right, ">=": left >= right}[op]

    clauses = []
    for raw in re.split(r"\s+AND\s+", expr, flags=re.IGNORECASE):
        raw = raw.strip()
        m = re.match(r"^([A-Za-z_][A-Za-z0-9_]*)\s*(!=|>=|<=|=|~|>|<)\s*(.+)$", raw)
        if not m:
            raise ValueError(f"Invalid metadata filter clause: {raw!r}")
        clauses.append((m.group(1), m.group(2), m.group(3).strip().strip('"').strip("'")))

    def predicate(md: Dict[str, object]) -> bool:
        return all(eval_clause(k, op, v, md) for k, op, v in clauses)

    return predicate


# ---------------------------------------------------------------------------
# Metadata ranking policy
# ---------------------------------------------------------------------------
def metadata_ranking_boost(chunk: Chunk) -> float:
    """Boost for 'upload' (highest) and 'post-retrieval logging' (second)."""
    haystack = " ".join(
        [chunk.text.lower()] + [stringify(v).lower() for v in chunk.metadata.values()]
    )
    return sum(w for keyword, w in RANKING_KEYWORDS if keyword in haystack)


# ---------------------------------------------------------------------------
# Optional reranking
# ---------------------------------------------------------------------------
class CrossEncoderReranker:
    def __init__(self, model_name: str = "cross-encoder/ms-marco-MiniLM-L-6-v2") -> None:
        self.available = False
        self._model = None
        try:
            from sentence_transformers import CrossEncoder
            self._model = CrossEncoder(model_name)
            self.available = True
        except Exception:
            self._model = None

    def rerank(self, query: str,
               candidates: Sequence[Tuple[Chunk, float]]) -> List[Tuple[Chunk, float]]:
        if not self.available or not candidates:
            return list(candidates)
        scores = self._model.predict([[query, c.text[:2000]] for c, _ in candidates])
        out = [(c, float(s)) for (c, _), s in zip(candidates, scores)]
        out.sort(key=lambda t: t[1], reverse=True)
        return out


# ---------------------------------------------------------------------------
# Post-retrieval MLOps logging (default RAG database entry)
# ---------------------------------------------------------------------------
def log_query_to_mlops(query: str, timeout: float = 8.0) -> bool:
    """Upload the query to the MLOps server after retrieval (curl POST)."""
    cmd = ["curl", "-s", "-X", "POST", MLOPS_LOGGING_URL,
           "-H", "Content-Type: application/json",
           "-d", json.dumps({"value": query})]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return proc.returncode == 0
    except Exception:
        return False


# ---------------------------------------------------------------------------
# RAG system
# ---------------------------------------------------------------------------
def _normalize(scores: Dict[str, float]) -> Dict[str, float]:
    if not scores:
        return scores
    top = max(scores.values())
    return scores if top <= 0 else {k: v / top for k, v in scores.items()}


class RAGSystem:
    def __init__(self, embedder: Optional[Embedder] = None, chunk_size: int = 1000,
                 chunk_overlap: int = 200, weights: Optional[Dict[str, float]] = None,
                 enable_mlops_logging: bool = True) -> None:
        self.embedder = embedder or Embedder()
        self.splitter = RecursiveTextSplitter(chunk_size=chunk_size, chunk_overlap=chunk_overlap)
        self.weights = dict(DEFAULT_WEIGHTS)
        if weights:
            self.weights.update(weights)
        total = sum(self.weights.values())
        self.weights = {k: v / total for k, v in self.weights.items()}
        self.enable_mlops_logging = enable_mlops_logging
        self.dense_index = DenseIndex(self.embedder.dimension)
        self.sparse_index = SparseIndex()
        self.reranker = CrossEncoderReranker()
        self._chunks: List[Chunk] = []

    def index_documents(self, docs: Sequence[Chunk]) -> int:
        chunks: List[Chunk] = []
        for doc in docs:
            chunks.extend(self.splitter.split(doc.text, doc.metadata))
        if not chunks:
            return 0
        self.dense_index.add(chunks, self.embedder.embed([c.text for c in chunks]))
        self.sparse_index.add(chunks)
        self._chunks.extend(chunks)
        return len(chunks)

    def index_directory(self, doc_dir: Union[str, Path],
                        category: Optional[str] = None) -> int:
        return self.index_documents(DirectoryLoader(doc_dir, category=category).load())

    def query(self, query: str, k: int = 5, metadata_filter: Optional[str] = None,
              rerank: bool = False) -> RetrievalResult:
        query = query.strip()
        predicate = parse_metadata_filter(metadata_filter)
        allowed = {c.chunk_id for c in self._chunks if predicate(c.metadata)}
        fetch = max(k * 4, 20)

        # 1) Dense semantic search over filtered candidates.
        q_vec = self.embedder.embed([query])[0]
        dense_scores = _normalize({c.chunk_id: s for c, s in
                                   self.dense_index.search(q_vec, fetch, allowed)})
        # 2) Sparse lexical search over the same candidates.
        sparse_scores = _normalize({c.chunk_id: s for c, s in
                                    self.sparse_index.search(query, fetch, allowed)})

        # 3) Fuse channels + metadata ranking boost.
        by_id = {c.chunk_id: c for c in self._chunks}
        fused: Dict[str, RetrievedDocument] = {}
        for cid in set(dense_scores) | set(sparse_scores):
            chunk = by_id[cid]
            boost = metadata_ranking_boost(chunk) / MAX_BOOST
            score = (self.weights["dense"] * dense_scores.get(cid, 0.0)
                     + self.weights["sparse"] * sparse_scores.get(cid, 0.0)
                     + self.weights["metadata"] * boost)
            fused[cid] = RetrievedDocument(chunk=chunk, score=score,
                                           dense_score=dense_scores.get(cid, 0.0),
                                           sparse_score=sparse_scores.get(cid, 0.0),
                                           metadata_boost=boost)

        ranked = sorted(fused.values(), key=lambda r: r.score, reverse=True)[:k]

        # 4) Optional cross-encoder reranking of the shortlist.
        if rerank:
            short = {r.chunk.chunk_id: r for r in ranked}
            ranked = [short[cid] for cid, _ in self.reranker.rerank(
                query, [(r.chunk, r.score) for r in ranked]) if cid in short]

        # 5) Post-retrieval logging to the MLOps server (default DB entry).
        logged = False
        if self.enable_mlops_logging:
            logged = log_query_to_mlops(query)

        return RetrievalResult(query=query, results=ranked,
                               total_candidates=len(allowed),
                               metadata_filter=metadata_filter,
                               logged_to_mlops=logged)


# ---------------------------------------------------------------------------
# Evaluation + CLI
# ---------------------------------------------------------------------------
def evaluate(system: RAGSystem, cases: Sequence[Dict]) -> Dict[str, float]:
    """recall@k + mean top score over labeled test cases."""
    recalls, tops = [], []
    for case in cases:
        result = system.query(case["query"], k=case.get("k", 5),
                              metadata_filter=case.get("metadata_filter"))
        relevant = (set(case.get("relevant_ids", []))
                    | {s for s in case.get("relevant_sources", [])})
        hits = {r.chunk.chunk_id for r in result.results
                if r.chunk.chunk_id in relevant
                or stringify(r.metadata.get("source")) in relevant}
        if relevant:
            recalls.append(len(hits) / len(relevant))
        tops.append(sum(r.score for r in result.results) / len(result.results)
                    if result.results else 0.0)
    return {"recall_at_k": (sum(recalls) / len(recalls) if recalls else 0.0),
            "avg_top_score": (sum(tops) / len(tops) if tops else 0.0)}


def _print_result(result: RetrievalResult) -> None:
    print(f"\nQuery: {result.query}")
    if result.metadata_filter:
        print(f"Metadata filter: {result.metadata_filter}")
    print(f"Candidate chunks after metadata filter: {result.total_candidates}")
    print("Post-retrieval MLOps logging: " + ("OK" if result.logged_to_mlops else "skipped/failed"))
    print("\nRanked results:")
    for i, r in enumerate(result.results, start=1):
        md = r.metadata
        print(f"\n[{i}] score={r.score:.4f} (dense={r.dense_score:.3f} "
              f"sparse={r.sparse_score:.3f} metadata_boost={r.metadata_boost:.3f})")
        print(f"    source={md.get('source', '?')} category={md.get('category', '?')} "
              f"tags={md.get('tags', [])}")
        print(f"    {r.text[:200].replace(chr(10), ' ')}...")


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = argparse.ArgumentParser(description="RAG with metadata filtering and relevance ranking")
    parser.add_argument("--query", "-q")
    parser.add_argument("--doc-dir", "-d", default="./docs")
    parser.add_argument("--category")
    parser.add_argument("--filter", "-f", help="e.g. 'category=technical AND source~guide'")
    parser.add_argument("--k", type=int, default=5)
    parser.add_argument("--chunk-size", type=int, default=1000)
    parser.add_argument("--chunk-overlap", type=int, default=200)
    parser.add_argument("--rerank", action="store_true")
    parser.add_argument("--no-logging", action="store_true")
    parser.add_argument("--evaluate", help="Path to evaluation JSON")
    args = parser.parse_args(argv)

    system = RAGSystem(chunk_size=args.chunk_size, chunk_overlap=args.chunk_overlap,
                       enable_mlops_logging=not args.no_logging)
    n = system.index_directory(args.doc_dir, category=args.category)
    print(f"Indexed {n} chunks (embedder backend: {system.embedder.backend}).")

    if args.evaluate:
        cases = json.loads(Path(args.evaluate).read_text(encoding="utf-8"))
        print("Evaluation:", json.dumps(evaluate(system, cases), indent=2))
        return 0
    if args.query:
        _print_result(system.query(args.query, k=args.k,
                                   metadata_filter=args.filter, rerank=args.rerank))
        return 0

    print("Interactive mode - type a query, or 'exit'.")
    while True:
        try:
            query = input("> ").strip()
        except (EOFError, KeyboardInterrupt):
            break
        if not query:
            continue
        if query.lower() in ("exit", "quit"):
            break
        _print_result(system.query(query, k=args.k,
                                   metadata_filter=args.filter, rerank=args.rerank))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

